import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Depthwise 2D convolution with a (K, 1) kernel.
// Each thread computes exactly one output element.
__global__ void depthwise_kx1_forward_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ out,
    int N, int C, int H, int W,
    int K, int Ho, int Wo,
    int stride, int pad, int dil)
{
    long idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
    long total = (long)N * C * Ho * Wo;
    if (idx >= total) return;

    int ow = (int)(idx % Wo);
    int oh = (int)((idx / Wo) % Ho);
    int c  = (int)((idx / ((long)Wo * Ho)) % C);
    int n  = (int)(idx / ((long)Wo * Ho * C));

    float acc = (b != nullptr) ? b[c] : 0.0f;

    const float* xp = x + ((long)n * C + c) * H * W + ow;
    const float* wp = w + (long)c * K;

    for (int k = 0; k < K; ++k) {
        int ih = oh * stride + k * dil - pad;
        if (ih >= 0 && ih < H) {
            acc += xp[(long)ih * W] * wp[k];
        }
    }
    out[idx] = acc;
}

torch::Tensor depthwise_kx1_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride, int64_t padding, int64_t dilation)
{
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "Weight must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "Input must be float32");

    auto xc = x.contiguous();
    auto wc = weight.contiguous();

    const int N = (int)xc.size(0);
    const int C = (int)xc.size(1);
    const int H = (int)xc.size(2);
    const int W = (int)xc.size(3);
    const int K = (int)wc.size(2); // weight shape: (C, 1, K, 1)

    const int Ho = (int)((H + 2 * padding - dilation * (K - 1) - 1) / stride + 1);
    const int Wo = (int)((W + 2 * padding - 1) / stride + 1);
    TORCH_CHECK(Ho > 0 && Wo > 0, "Invalid output size");

    auto out = torch::empty({N, C, Ho, Wo}, xc.options());

    const float* bptr = nullptr;
    torch::Tensor bc;
    if (bias.has_value() && bias->defined()) {
        bc = bias->contiguous();
        bptr = bc.data_ptr<float>();
    }

    long total = (long)N * C * Ho * Wo;
    int threads = 256;
    int blocks = (int)((total + threads - 1) / threads);

    auto stream = at::cuda::getCurrentCUDAStream();
    depthwise_kx1_forward_kernel<<<blocks, threads, 0, stream>>>(
        xc.data_ptr<float>(),
        wc.data_ptr<float>(),
        bptr,
        out.data_ptr<float>(),
        N, C, H, W, K, Ho, Wo,
        (int)stride, (int)padding, (int)dilation);

    return out;
}
"""

cpp_src = r"""
torch::Tensor depthwise_kx1_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride, int64_t padding, int64_t dilation);
"""

_depthwise_kx1 = load_inline(
    name="depthwise_kx1_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["depthwise_kx1_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Depthwise 2D convolution with an asymmetric (kernel_size, 1) kernel,
    implemented with a custom CUDA kernel.
    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv2d = nn.Conv2d(
            in_channels, in_channels,
            kernel_size=(kernel_size, 1),
            stride=stride, padding=padding,
            dilation=dilation, groups=in_channels, bias=bias
        )
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            x = x.cuda()
        weight = self.conv2d.weight
        bias = self.conv2d.bias
        if weight.device != x.device:
            weight = weight.to(x.device)
        if bias is not None and bias.device != x.device:
            bias = bias.to(x.device)
        return _depthwise_kx1.depthwise_kx1_forward(
            x, weight, bias, self.stride, self.padding, self.dilation
        )

